'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['createSignalHub']);
const { createSignalHub } = api;
const hub = createSignalHub();
assert.equal(typeof hub.on, 'function');
assert.equal(typeof hub.off, 'function');
assert.equal(typeof hub.publish, 'function');

for (const topic of ['', null, 3]) {
  assert.throws(() => hub.publish(topic, null), TypeError);
  assert.throws(() => hub.on(topic, () => {}), TypeError);
}
assert.throws(() => hub.on('topic', null), TypeError);
assert.throws(() => hub.off('topic', null), TypeError);
assert.equal(hub.publish('unused', 1), 0);

const events = [];
const payload = Object.freeze({ value: 7 });
function first(value) {
  events.push(['first', value]);
}
function second(value) {
  events.push(['second', value]);
}
const unsubscribeFirst = hub.on('topic', first);
assert.equal(typeof unsubscribeFirst, 'function');
hub.on('topic', first);
hub.on('topic', second);
assert.equal(hub.publish('topic', payload), 2);
assert.deepEqual(events, [['first', payload], ['second', payload]]);
assert.strictEqual(events[0][1], payload);
assert.equal(hub.off('topic', first), true);
assert.equal(hub.off('topic', first), false);
assert.equal(hub.publish('topic', payload), 1);
unsubscribeFirst();

const snapshotHub = createSignalHub();
const snapshotEvents = [];
function added() { snapshotEvents.push('added'); }
function later() { snapshotEvents.push('later'); }
function changing() {
  snapshotEvents.push('changing');
  snapshotHub.off('snap', later);
  snapshotHub.on('snap', added);
}
snapshotHub.on('snap', changing);
snapshotHub.on('snap', later);
assert.equal(snapshotHub.publish('snap'), 2);
assert.deepEqual(snapshotEvents, ['changing', 'later']);
snapshotEvents.length = 0;
assert.equal(snapshotHub.publish('snap'), 2);
assert.deepEqual(snapshotEvents, ['changing', 'added']);

const failure = new Error('handler failure');
let afterFailure = false;
snapshotHub.on('errors', () => { throw failure; });
snapshotHub.on('errors', () => { afterFailure = true; });
assert.throws(() => snapshotHub.publish('errors', 1), (error) => error === failure);
assert.equal(afterFailure, false);

